targets.query:
import "date"
import "dict"
import "strings"
rename = (rule, field, s) =>
    if rule == "L3-01-V" and field == "cond_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"C1\"", u: "\"min_connection\""), t: "\"C2\"", u: "\"noreply_ratio\""), t: "\"C3\"", u: "\"connection_increase\""), t: "\"C2a\"", u: "\"absolute_value\"")
    else if rule == "L3-01-V" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: s, t: "\"uectx\":", u: "\"uectxmax\":"), t: "\"max_conn\":", u: "\"max_connection\":")
    else if rule == "L3-01-V" and field == "params_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"z\":", u: "\"sigma_multiplier\":"), t: "\"theta\":", u: "\"noreply_ratio_threshold\":"), t: "\"f_abs_frac\":", u: "\"absolute_value_ratio\":"), t: "\"f_abs\":", u: "\"absolute_value_threshold\":")
    else if rule == "L3-01-V" and field == "refs_json" then strings.replaceAll(v: strings.replaceAll(v: s, t: "\"a\":", u: "\"connection_sequence_range\":"), t: "\"f\":", u: "\"noreply_sequence_range\":")
    else if rule == "L3-01-O" and field == "cond_json" then strings.replaceAll(v: s, t: "\"stall_count\"", u: "\"authentication_stall_count\"")
    else if rule == "L3-01-O" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"stalls_w\":", u: "\"stalls_window\":"), t: "\"auth_req_w\":", u: "\"authentication_request_window\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":"), t: "\"uectx\":", u: "\"uectxmax\":")
    else if rule == "L3-01-O" and field == "params_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"auth_wait_ms\":", u: "\"authentication_wait_ms\":"), t: "\"n_stall\":", u: "\"stall_count_minimum\":"), t: "\"n_stall_frac\":", u: "\"stall_count_ratio\":"), t: "\"n_stall_th\":", u: "\"stall_count_threshold\":"), t: "\"max_conn\":", u: "\"max_connection\":")
    else if rule == "L3-20" and field == "cond_json" then strings.replaceAll(v: strings.replaceAll(v: s, t: "\"concurrent\"", u: "\"victim_connected\""), t: "\"not_accepted\"", u: "\"network_not_accepted\"")
    else if rule == "L3-20" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"concurrent\":", u: "\"victim_connected_count\":"), t: "\"peer_uncertain\":", u: "\"victim_uncertain_count\":"), t: "\"victims\":", u: "\"victim_count\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":")
    else if rule == "L3-21" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"fails_w\":", u: "\"fails_window\":"), t: "\"branch1_ues\":", u: "\"cell_fail_increase_count\":"), t: "\"branch2_ues\":", u: "\"registration_repeat_fail_count\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":"), t: "\"fail_msgs_w\":", u: "\"fail_messages_window\":")
    else if rule == "L3-21" and field == "params_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"n_fail\":", u: "\"fail_count_minimum\":"), t: "\"n_fail_frac\":", u: "\"fail_count_ratio\":"), t: "\"n_fail_th\":", u: "\"fail_count_threshold\":"), t: "\"reg_repeat\":", u: "\"registration_repeat\":"), t: "\"max_conn\":", u: "\"max_connection\":")
    else if rule == "L3-24" and field == "cond_json" then strings.replaceAll(v: s, t: "\"unsolicited\"", u: "\"unsolicited_identity_response\"")
    else if rule == "L3-24" and field == "conditions_json" then strings.replaceAll(v: s, t: "\"mitm_ul_relay\"", u: "\"mitm_uplink_relay\"")
    else if rule == "L3-24" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"extra\":", u: "\"same_connection_repeat\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":")
    else if rule == "L3-14" and field == "cond_json" then strings.replaceAll(v: s, t: "\"unsolicited\"", u: "\"unsolicited_capability_information\"")
    else if rule == "L3-14" and field == "conditions_json" then strings.replaceAll(v: s, t: "\"mitm_ul_relay\"", u: "\"mitm_uplink_relay\"")
    else if rule == "L3-14" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"branch1_ues\":", u: "\"unsolicited_capability_count\":"), t: "\"branch2_ues\":", u: "\"enquiry_before_security_count\":"), t: "\"extra\":", u: "\"same_connection_repeat\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":")
    else if rule == "L3-06" and field == "cond_json" then strings.replaceAll(v: s, t: "\"unsolicited\"", u: "\"unsolicited_security_mode_reject\"")
    else if rule == "L3-06" and field == "conditions_json" then strings.replaceAll(v: s, t: "\"mitm_ul_relay\"", u: "\"mitm_uplink_relay\"")
    else if rule == "L3-06" and field == "values_json" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"extra\":", u: "\"same_connection_repeat\":"), t: "\"held\":", u: "\"judgment_held\":"), t: "\"evicted\":", u: "\"table_evicted\":")
    else s
hide_candidates = (rule, s) =>
    if rule == "AN-02" then strings.replaceAll(v: strings.replaceAll(v: strings.replaceAll(v: s, t: "\"L3-25-OV\",", u: ""), t: ",\"L3-25-OV\"", u: ""), t: "\"L3-25-OV\"", u: "")
    else s
labels = dict.fromList(pairs: [{key: "cond_json", value: "성립 조건 (cond)"}, {key: "candidates_json", value: "같은 모양의 다른 공격 후보 (candidates)"}, {key: "conditions_json", value: "공격자 행동 전제 (conditions)"}, {key: "values_json", value: "관측값 (values, 마지막 값)"}, {key: "params_json", value: "설정값 (params)"}, {key: "refs_json", value: "판정 창 seq 범위 (refs)"}])
order = dict.fromList(pairs: [{key: "cond_json", value: 0}, {key: "candidates_json", value: 1}, {key: "conditions_json", value: 2}, {key: "values_json", value: 3}, {key: "params_json", value: 4}, {key: "refs_json", value: 5}])
from(bucket: v.defaultBucket)
  |> range(start: date.sub(d: 6h, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "alert" and r.env == "${source}" and r.alert_id == "${alert_id}")
  |> filter(fn: (r) => r._field == "cond_json" or r._field == "candidates_json" or r._field == "conditions_json" or r._field == "values_json" or r._field == "params_json" or r._field == "refs_json")
  |> group(columns: ["_field"])
  |> max(column: "_time")
  |> group()
  |> map(fn: (r) => ({n: dict.get(dict: order, key: r._field, default: 99),
      항목: dict.get(dict: labels, key: r._field, default: r._field),
      값: rename(rule: r.rule, field: r._field,
          s: if r._field == "candidates_json" then hide_candidates(rule: r.rule, s: string(v: r._value)) else string(v: r._value))}))
  |> sort(columns: ["n"])
  |> drop(columns: ["n"])
